function validate([n]) {
  if (!Number.isInteger(n)) return 'n must be a whole number.';
  if (n < 1 || n > 100000000) return 'n is between 1 and 10^8.';
  return null;
}

reference:
function isArmstrong(n) {
  let k = 0;
  let rest = n;
  while (rest > 0) {
    k++;
    rest = Math.floor(rest / 10);
  }

  let sum = 0;
  rest = n;
  while (rest > 0) {
    const digit = rest % 10;
    sum += digit ** k;
    rest = Math.floor(rest / 10);
  }
  return sum === n;
}

brute:
function isArmstrong(n) {
  // Work on the decimal text instead of arithmetic on the number.
  const text = String(n);
  let total = 0;
  for (const ch of text) {
    let power = 1;
    for (let i = 0; i < text.length; i++) power *= Number(ch);
    total += power;
  }
  return total === n;
}

generator:
function generate(rand, size) {
  const armstrong = [1, 2, 3, 4, 5, 6, 7, 8, 9, 153, 370, 371, 407, 1634, 8208, 9474, 54748, 92727, 93084, 548834, 1741725, 4210818, 9800817, 9926315, 24678050, 24678051, 88593477];
  const pick = rand();
  if (pick < 0.3) return [armstrong[Math.floor(rand() * armstrong.length)]];
  if (pick < 0.45) {
    // A neighbour of an Armstrong number: close in value but (almost always) not one.
    const near = armstrong[Math.floor(rand() * armstrong.length)] + Math.floor(rand() * 5) - 2;
    return [Math.min(100000000, Math.max(1, near))];
  }
  const digits = size === 'large' ? 6 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 8);
  const low = 10 ** (digits - 1);
  return [low + Math.floor(rand() * (9 * low))];
}
